ALTER POLICY "alerts_own_rows" ON "alerts" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and not exists (select 1 from unnest(alerts.transaction_ids) x(id) where not exists (select 1 from transactions t where t.id = x.id)));--> statement-breakpoint
ALTER POLICY "audit_log_own_rows" ON "audit_log" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (audit_log.proposal_id is null or exists (select 1 from proposed_actions p where p.id = audit_log.proposal_id)));--> statement-breakpoint
ALTER POLICY "bills_own_rows" ON "bills" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (bills.account_id is null or exists (select 1 from accounts p where p.id = bills.account_id)));--> statement-breakpoint
ALTER POLICY "budgets_own_rows" ON "budgets" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (budgets.category_id is null or exists (select 1 from categories p where p.id = budgets.category_id)));--> statement-breakpoint
ALTER POLICY "rules_own_rows" ON "rules" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (rules.category_id is null or exists (select 1 from categories p where p.id = rules.category_id)));--> statement-breakpoint
ALTER POLICY "statements_own_rows" ON "statements" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (statements.account_id is null or exists (select 1 from accounts p where p.id = statements.account_id)) and (statements.import_id is null or exists (select 1 from imports p where p.id = statements.import_id)));--> statement-breakpoint
ALTER POLICY "transaction_tags_own_rows" ON "transaction_tags" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (transaction_tags.transaction_id is null or exists (select 1 from transactions p where p.id = transaction_tags.transaction_id)) and (transaction_tags.tag_id is null or exists (select 1 from tags p where p.id = transaction_tags.tag_id)));--> statement-breakpoint
ALTER POLICY "transactions_own_rows" ON "transactions" TO app_user USING (user_id = current_setting('app.user_id', true)) WITH CHECK (user_id = current_setting('app.user_id', true) and (transactions.account_id is null or exists (select 1 from accounts p where p.id = transactions.account_id)) and (transactions.statement_id is null or exists (select 1 from statements p where p.id = transactions.statement_id)) and (transactions.category_id is null or exists (select 1 from categories p where p.id = transactions.category_id)));